// based on abje http://shadertoy.com/view/4sVfWw
// instead of instanced shapes at various scales,
// surf which level sampling some complex shape at, 
// based on full, empty, surface classification

// it seems working pretty well now.  Hope it's useful.

// TODO mix with e.g. http://shadertoy.com/view/M3fSWs

// TODO I still intend to try to simplify the algorithm more; 
// there were several parts about it that I found confusing.

//#define coarseness 1. // TODO want to control size of biggest octree cell (always subdivide up to this)
// somehow when I try, it breaks everything

#define detail 3
#define steps 64
#define time (iTime*0.1)
#define maxdistance 5.0

#define fog 1
#define drawgrid 0
#define borders 1

#define raymarchhybrid 96 //0 //
#define tintlevels 1
#define lighting 1
#define cutawayfront 1
#define cutawayhole 0
#define cutawaysdf 0

#define pi radians(180.)

#define rot(a) mat2(cos(a), sin(a),-sin(a), cos(a))

#define sqr(a) dot(a, a)

// following iq method
float dBox(vec3 q, vec3 e)
{
    q = abs(q) - e;
    float g = max(q.x, max(q.y, q.z));
    return g <= 0. ? g : length(max(q, 0.));
}

float dOctahedron(vec3 p, float s) // by Iq 2019
{
    p = abs(p);
    float m = p.x + p.y + p.z - s;
         if (3. * p.x < m) p = p.xyz;
    else if (3. * p.y < m) p = p.yzx;
    else if (3. * p.z < m) p = p.zxy;
    else return m * sqrt(1./3.); //.57735027;    
    float k = clamp(.5 * (p.z - p.y + s), 0., s); 
    return length(p - vec3(0, s-k, k));
}


float shape(vec3 q)
{
    float d;
    //d = length(q) - .9;
    //d = abs(length(q) - .8) - .2;
    d = length(vec2(length(q.xz) - 1.0, q.y)) - .66; // torus
    //d = .7 * sqrt(1./3.) * (abs(q.x) + abs(q.y) + abs(q.z)) - .5; // simple octahedron
    //d = dBox(q, vec3(.95, .84, .73)) - .05;
    //d = dOctahedron(q, 1.1) - .1;
 #if cutawaysdf
    d = max(d, .45 - max(abs(q.x), abs(q.y)));   // chops a square hole thru the object sdf
 #endif
    return d;
}

// at first I enabled the inner raymarchhybrid feature to show copies of shapes within the cubes.
// now I've gone past that multilevel truchet style, and am showing some larger shape.

// 0 is empty, 1 is subdivide and 2 is full
int getvoxel(vec3 p, float size) 
{
 #if cutawayhole
    if (max(abs(p.x + .0), abs(p.y + .0)) < .15) {
        return 0; // chops a square hole thru the object in a way that exposes the octree cells
    }
 #endif
 #if cutawayfront
    if (p.z > .0) { //.5) {
        return 0; // chops front half or quarter
    }
 #endif
    // subdivide according to shape function adjacency - does the cell contain the shape (probably?)
    float d = shape(p);
    float lim = sqrt(3.) * .5 * size;
    if (d > lim) {
        return 0;
    } else if (d > -lim) {
        return 1;
    } else {
        return 2;
    }
}
