// ray-cube intersection, on the inside of the cube
// ird = 1. / abs(rd)
vec3 voxel(vec3 ro, vec3 rd, vec3 ird, float size)
{
    size *= .5;
    return (size - sign(rd) * (ro - size)) * ird;
}

float map(vec3 w) // w = world space position
{
    return shape(w);
}

vec3 grad(vec3 p, float epsilon)
{
    vec2 e = vec2(0, epsilon);
    return vec3(
        map(p + e.yxx), 
        map(p + e.xyx), 
        map(p + e.xxy) 
        ) - map(p);
}

vec3 trace(vec3 ro, vec3 rd)
{
    vec3 c; // returned
    vec2 r = iResolution.xy;
    float size = 1.;
    //size *= coarseness; // wasn't working as expected yet
    vec3 fro = floor(ro / size) * size; // current cell "origin"
    vec3 lro = ro - fro; // "fractional" offset within cell
    //vec3 lro = mod(ro, size);
    //vec3 fro = ro - lro;
    vec3 ird = 1.0 / max(abs(rd), 1e-4);
    vec3 mask;
    vec3 lastmask;
    bool exitoct = false;
    bool yhit = false;
    int recursions = 0;
    float dist = 0.0;
    float fdist = 0.0;
    float edge = 1.0, edge2 = 1.0;
    float e = 1e-4; // / size;

    // octree traversal loop
    // each iteration either:
    // - check if need to go up a level
    // - check if need to go down a level
    // - check if hit a solid cell or what
    // - march fine detail if cell is not empty and we're at max subdivision
    // - go one step forward if cell is empty
    // - repeat if did not hit a solid cell
    int i;
    for (i = 0; i < steps; ++i)
    {
        if (dist > maxdistance) break;

        // not sure this made sense to use lro actually
        vec3 cp = fro + lro; // basically dist * rd + ro, current position along ray, likely on a cell boundary
        vec3 cc = fro + .5 * size; // cell center

        // go up a level?
        if (exitoct)
        {
            vec3 newfro = floor(fro / (size * 2.0)) * (size * 2.0);

            lro += fro - newfro;
            fro = newfro;

            --recursions;
            size *= 2.0;

            exitoct = (recursions > 0) && 
              (abs(dot(mod(fro / size + 0.5, 2.0) - 1.0 + mask * sign(rd) * 0.5, mask)) < 0.1);
        }
        else
        {
            // check what type of cell it is: empty, full or subdivide
            int voxelstate = getvoxel(cc, size);

            if (voxelstate == 1 && recursions > detail)
            {
                voxelstate = 2;
            }

            if (voxelstate == 1 && recursions <= detail)
            {
                // if (recursions > detail) break;

                ++recursions;
                size *= .5;

                // find which of 8 sub-voxels will be entered
                vec3 mask2 = step(vec3(size), lro);
                fro += mask2 * size;
                lro -= mask2 * size;

                continue;
            }
            // move forward
            //else 
            if (voxelstate == 0 || voxelstate == 2)
            {
                // raycast and find distance to nearest voxel surface in ray direction
                // don't need to use voxel() every time, but do anyway
                vec3 hit = voxel(lro, rd, ird, size);

                mask = vec3(lessThan(hit, min(hit.yzx, hit.zxy)));
                float len = dot(hit, mask);

                if (voxelstate == 2) // hit recursion limit or full solid?
                {
                 #if raymarchhybrid
                    //if (length(fro - ro) > 20.0 * size) break; // detail only near camera!
                    vec3 p = cp;
                    float d = 0.0;
                    e = 3e-3 * dist;
                    if (recursions <= detail) { // "solid" cell
                        yhit = true;
                        break;
                    }
                    else
                    for (int j = 0; j < raymarchhybrid && d <= len; ++j) {
                        float l = map(p);
                        if (l < e) {
                            yhit = true;
                            break;
                        }
                        p += l * rd;
                        d += l;
                    }
                    if (yhit) {
                        d = min(len, d);
                        dist += d;
                        break;
                    }
                 #else
                    break;
                 #endif
                }

                // move forward in ray direction, and check if need to go up a level
                dist += len;
                fdist += len;
                lro += rd * len - mask * sign(rd) * size;
                vec3 newfro = fro + mask * sign(rd) * size;
                exitoct = (floor(newfro / size * .5 + .25) != floor(fro / size * .5 + .25))
                       && (recursions > 0);
                fro = newfro;
                lastmask = mask;
            }
        }
     #if drawgrid
        vec3 q = abs(lro / size - .5) * (1. - lastmask);
        edge2 = min(edge2, -(max(max(q.x, q.y), q.z) - 0.5) * r.y * .5 * size);
     #endif
    }
    ro += dist * rd;
    #if !raymarchhybrid
    vec3 n = -lastmask * sign(rd);
    #else
    vec3 n = normalize(grad(ro, e));
    #endif

    if (i < steps && dist < maxdistance)
    {
    	float val = fract(dot(fro, vec3(15.23, 754.345, 3.454)));
        vec3 color = vec3(1);
     #if tintlevels
        if (yhit) color *= sin(vec3(0, 2, 4) + 2. / size) * .5 + .5;
     #endif
     #if lighting
        vec3 lite = max(.5, dot(n, vec3(-1,-1,1) * .566)) * vec3(1);
    	c = vec3(color * lite);
        vec3 dpl = vec3(1,-2,2) - ro;
        vec3 lite2 = max(.0, dot(n, normalize(dpl))) / (2.2 * sqr(dpl) + .01) * vec3(0, .3, 0);
    	c += vec3(color * lite2);
     #else
        c = color;
     #endif

     #if borders
        vec3 q = abs(lro / size - .5) * (1. - lastmask);
        edge = clamp((.5 - max(max(q.x, q.y), q.z)) * r.y * .25 * size / dist, 0., 1.);
        if (yhit)
          c += (1. - edge) * (1. - c); //c = mix(vec3(1), c, edge); // white cell borders
     #endif

     #if drawgrid
        c *= edge2;
     #endif
   } else {
     #if drawgrid
        c = vec3(edge2);
     #endif
   }
 #if fog
    c *= 1. - .9 * dist / maxdistance;
 #endif
    return c;
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    vec4 m = iMouse;
    vec2 r = iResolution.xy,
        q = (2. * fragCoord.xy - r) / r.y;

    vec3 ro = vec3(.0 + .4 * sin(5. * time), .0 + .4 * cos(5. * time), 1.5 + .0 * cos(time)),
        rd = normalize(vec3(q, 1));

    // rotate camera by mouse
    rd.yz *= rot(m.y / r.y * 2. * pi - pi);
    rd.xz *= rot(m.x / r.x * 4. * pi - 2. * pi);

    vec3 c = trace(ro, rd);

    fragColor = vec4(sqrt(c), 1);
}
